/**
 * The canon checks (docs/CONSTITUTION.md): what `kit check canon` runs against a repository's kit.canon.json.
 *
 *   schemas     every declared data file / module export is valid against its JSON Schema (2020-12)
 *   contracts   every declared OpenAPI 3.1 contract is structurally valid and matches the routes in the code, both ways;
 *               every JSON Schema contract compiles and its handlers exist
 *   hardcoding  no project names, project URLs, colours, reader-facing copy or secrets in code outside the reviewed
 *               allow-list (canon.allow.json); allow-list entries that match nothing are stale and fail too
 *   freshness   every generated artefact's check command exits 0 (generated files are never hand-edited)
 *   diagrams    every Mermaid source is on the project's theme, has a fresh PNG and carries a valid kit:diagram header (id, lineage,
 *               relationships; no duplicate ids, dangling references, cycles or missing depicts paths: the `kit diagrams check` rules)
 *   digits      rendered Persian output (HTML, SVG, Markdown twins, llms.txt) shows every number in Persian digits
 *               (@saasreport/format/scan; exemptions: code, URLs, Latin identifiers, data-digits="latin" with a reason)
 *   sdk         every OpenAPI contract has its SDK generated by @saasreport/forge (kit.sdk.json), current, never hand-edited,
 *               and no hand-written client duplicates it (@saasreport/sdk, docs/SDK.md)
 *   vendor      the vendored kit snapshot matches its manifest (commit + sha256 per file; ../vendor.js)
 *   persian     the project's Persian copy (persian.config.json) passes the Persian rule pack (@saasreport/fa-lint): typography,
 *               ZWNJ, digits, bidi and the owner's corrections of wording and word order; podcast scripts too (docs/PERSIAN.md)
 *   spelling    a British English project's content carries no American spelling outside code, URLs and its reviewed
 *               exceptions (spelling.js; the word list is @saasreport/core/spelling, shared with the podcast check)
 *   claude      the Claude Code token-cost standard (docs/COST.md): settings and agents match claude.policy.json, every agent
 *               has model + maxTurns, CLAUDE.md within the line limit, every scripted agent loop has a budget (../claude.js)
 *   enforcement the ONE constitution registry (constitution.rules.json; docs/AGENT-GUARD.md): every layer a rule claims exists here: guard hooks
 *               installed and intact, agent scopes declared, canon first in npm test, a PR workflow, gated deploys, no empty alert recipients,
 *               the generated ruleset and CLAUDE.md block current. Never waivable.
 *   resilience  resilience.json (docs/RESILIENCE.md): a monitor that is told where to send, writes to its own D1, reports a stale status and has an
 *               independent dead-man; every D1/R2 has a backup in another resource; drills with proof, fresh
 *   release     release.json (docs/RELEASE.md): one production workflow (the kit template) in environment production, the tested artefact is the
 *               deployed one, every D1 migrated before its Workers, every Worker serves its commit on /api/build, /api/health derived from the
 *               monitor, one owner address, no shell deploy, bootstrap only before the first deploy
 *   migrations  every migrations/*.sql of the repository (a D1 binding's migrations_dir, and every migrations/ directory of its own tree) is RUN in order on
 *               a fresh local D1 per binding (SQLite behind D1's measured limits, no network) and fails on any statement D1 would reject, or any
 *               trigger, view or table left with a GLOB/LIKE pattern over D1's 50 bytes (../migrations-d1.js; the 2026-10-07 podcast outage). Applies
 *               wherever migrations exist, no configuration to forget; none at all is "not applicable", proven from the files
 *   concepts    a concept series (concepts.config.json, docs/CONCEPTS.md): catalogue, schedule, source proof and, for a Shariah series, the signed
 *               approval ledger and the roster. Applies whenever the file exists: a repository cannot declare its way out of it
 *   tokens      no design-token colour is written as a literal outside the token sources (tokens.js)
 *   findings    every finding class (finding-classes.json) has a gate proven on its real case, and no gate finds anything in the
 *               repository outside one-instance reviewed allow entries (findings.js, engine.js: every rule a declared contract; §10
 *               zero post-facto); among them the CI policy of kit.canon.json `workflows`: CI exists and runs on the one declared
 *               runner image (no `*-latest`), canaries never block and are reviewed by their date, no action floats on a branch
 *               (ci-runner-pinned, ci-action-pinned, ci-workflow-exists, ci-canary-expired; declared contracts, no module of their own)
 *
 * runCanon(root, { only, spawn }) → { ok, results: { <check>: { ok, summary, problems: [{ file, problem }] } } }
 */
import { existsSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath, pathToFileURL } from "node:url";
import { createValidator, formatProblems } from "@saasreport/core/schema";
import { expand, matchesAny, readText, walk } from "./files.js";
import { scanHardcoding, countBy } from "./hardcoding.js";
import { checkDiagrams as checkDiagramRepo } from "../diagram-lineage.js";
import { isSourceMode, kitLocation } from "../vendor-path.js";
import { checkVendor } from "../vendor.js";
import { staleProblems } from "../vendor-stale.js";
import { checkSpelling } from "./spelling.js";
import { checkTokenLiterals } from "./tokens.js";
import { checkClaude } from "../claude.js";
import { checkResilience } from "../resilience/check.js";
import { checkRelease } from "../release/check.js";
import { migrationsCheck } from "../migrations-d1.js";
import { checkEnforcement } from "../agent-guard/install.js";
import { checkConceptsRepo } from "../concepts.js";
import { checkFindings } from "./findings.js";
import { capabilityContractProblems } from "./capabilities.js";
import { checkPersian, codeownersCover } from "./persian.js";
import { ALWAYS, PREDICATES, repoFacts, deployScan } from "./facts.js";
import { scanDigits, isPersianHtml, typeOf } from "@saasreport/format/scan";
// the sibling package by path: present wherever the CLI is (the kit, a vendored snapshot), no extra dependency to declare
import { checkSdk } from "../../../sdk/src/index.js";

export const CHECKS = ["schemas", "contracts", "sdk", "hardcoding", "freshness", "diagrams", "digits", "persian", "vendor", "spelling", "tokens", "claude", "enforcement", "resilience", "release", "findings", "concepts", "migrations"];
export const CANON_FILE = "kit.canon.json";

import { bundled } from "../bundled.js";
import { SourceError, siteProblems, sourceConfig, verify as verifySource } from "../source.js";
export { bundled };

const readJson = (root, file) => JSON.parse(readFileSync(join(root, file), "utf8"));
const P = (file, problem) => ({ file, problem });

/** kit.canon.json at root, validated: { canon, problems }. */
export function loadCanon(root, kit = bundled()) {
  const file = join(root, CANON_FILE);
  if (!existsSync(file)) return { canon: null, problems: [P(CANON_FILE, "missing: every repository declares its canon (docs/CONSTITUTION.md §5)")] };
  let canon;
  try { canon = JSON.parse(readFileSync(file, "utf8")); } catch (e) { return { canon: null, problems: [P(CANON_FILE, `not JSON: ${e.message}`)] }; }
  const problems = formatProblems(kit.validator.validate(canon, kit.byName("canon"))).map((m) => P(CANON_FILE, m));
  const known = new Set(kit.registry.projects.map((p) => p.key).concat("kit"));
  if (canon.project && !known.has(canon.project)) problems.push(P(CANON_FILE, `project "${canon.project}" is not in the registry (packages/core/registry/projects.json)`));
  return { canon, problems };
}

/** A schema reference (bundled name, $id or repo path) → the schema object (registered with the validator). */
function schemaOf(root, ref, kit) {
  const named = kit.byName(ref);
  if (named) return named;
  if (/^https?:\/\//.test(ref)) return kit.validator.get(ref) || null;
  const file = join(root, ref);
  if (!existsSync(file)) return null;
  const s = JSON.parse(readFileSync(file, "utf8"));
  if (s.$id && !kit.validator.has(s.$id)) kit.validator.add(s);
  return s;
}

async function moduleValue(root, rule) {
  const mod = await import(pathToFileURL(resolve(root, rule.module)).href);
  const name = rule.export || "default";
  if (!(name in mod)) throw new Error(`no export "${name}"`);
  let v = mod[name];
  if (rule.call) v = await v();
  return v;
}

/** schemas: every declared file and module export against its schema. */
export async function checkSchemas(root, canon, kit = bundled()) {
  const problems = [];
  let checked = 0;
  for (const rule of canon.schemas || []) {
    const schema = schemaOf(root, rule.schema, kit);
    const where = rule.module ? `${rule.module}${rule.export && rule.export !== "default" ? `#${rule.export}` : ""}` : (rule.files || []).join(", ");
    if (!schema) { problems.push(P(where, `unknown schema "${rule.schema}" (a bundled name, an $id or a path)`)); continue; }
    const targets = [];
    if (rule.module) {
      try { targets.push([where, await moduleValue(root, rule)]); } catch (e) { problems.push(P(where, `cannot load: ${e.message}`)); continue; }
    } else {
      const files = expand(root, rule.files);
      if (!files.length) { problems.push(P(where, "matches no file (a declared schema rule must cover something)")); continue; }
      for (const f of files) {
        try { targets.push([f, readJson(root, f)]); } catch (e) { problems.push(P(f, `not JSON: ${e.message}`)); }
      }
    }
    for (const [label, value] of targets) {
      const items = rule.each ? (Array.isArray(value) ? value.map((x, i) => [`${label}[${i}]`, x]) : [[label, value]]) : [[label, value]];
      if (rule.each && !Array.isArray(value)) { problems.push(P(label, "each: true needs an array")); continue; }
      for (const [l, x] of items) {
        checked++;
        for (const m of formatProblems(kit.validator.validate(x, schema))) problems.push(P(l, `${rule.schema}: ${m}`));
      }
    }
  }
  return { ok: !problems.length, configured: (canon.schemas || []).length > 0, checked, summary: `${checked} value${checked === 1 ? "" : "s"} against ${(canon.schemas || []).length} schema rule${(canon.schemas || []).length === 1 ? "" : "s"}`, problems };
}

const DEFAULT_ROUTES = String.raw`(?<![\w.])/(?:api(?:/[A-Za-z0-9._{}-]+)*/?|mcp)(?![\w/])`;
const toTemplate = (p) => p.replace(/\$\{[^}]*\}/g, "{}").replace(/\{[^}]*\}/g, "{}");
/** Canonical OpenAPI templated path also covers a concrete route literal.
 * Example: /api/forms/{form} is the contract for /api/forms/sandbox-key.
 * Matching is per-segment only: no prefix-only, greedy or partial match.
 */
export const contractPathCovers = (template, route) => {
  const a = toTemplate(template).split("/"), b = toTemplate(route).split("/");
  return a.length === b.length && a.every((part, i) => part === "{}" || part === b[i]);
};


/** The route literals in sources: Set of paths (template expressions folded to {}). */
export function routeLiterals(root, sources, pattern = DEFAULT_ROUTES) {
  const re = new RegExp(pattern, "g");
  const out = new Set();
  for (const f of expand(root, sources).filter((x) => /\.(m?js|ts)$/.test(x))) {
    const src = readText(root, f);
    for (const m of src.matchAll(/(["'`])((?:\\.|(?!\1).)*)\1/g)) {
      for (const r of toTemplate(m[2]).matchAll(re)) out.add(r[0]);
    }
    // anchored regex routes: /^\/api\/forms\/([a-z-]+)$/ → /api/forms/{}
    for (const m of src.matchAll(/\/\^((?:\\\/(?:[^\\\s/$]|\\[^/])*)+)\$?\//g)) {
      const path = m[1].replace(/\\\//g, "/").replace(/\((?:[^()]|\([^()]*\))*\)[?*+]?/g, "{}").replace(/\\(.)/g, "$1");
      if (!/[[\]|^$*+?]/.test(path)) for (const r of path.matchAll(re)) out.add(r[0]);
    }
  }
  return out;
}

/** contracts: OpenAPI documents match their routes; JSON Schema contracts compile; handlers exist. */
export function checkContracts(root, canon, kit = bundled()) {
  const problems = [];
  let n = 0;
  for (const c of canon.contracts || []) {
    n++;
    const file = c.contract;
    if (!existsSync(join(root, file))) { problems.push(P(file, `contract "${c.name}" is missing`)); continue; }
    let doc;
    try { doc = readJson(root, file); } catch (e) { problems.push(P(file, `not JSON: ${e.message}`)); continue; }
    for (const h of c.handlers || []) if (!existsSync(join(root, h))) problems.push(P(h, `handler of contract "${c.name}" does not exist`));
    if (c.type === "json-schema") {
      if (doc.$schema !== "https://json-schema.org/draft/2020-12/schema") problems.push(P(file, "a JSON Schema contract declares $schema https://json-schema.org/draft/2020-12/schema"));
      if (!doc.$id) problems.push(P(file, "a JSON Schema contract has an $id"));
      try { createValidator([doc]).validate(null, doc); } catch (e) { problems.push(P(file, `does not compile: ${e.message}`)); }
      continue;
    }
    for (const m of formatProblems(kit.validator.validate(doc, kit.byName("openapi")))) problems.push(P(file, `openapi: ${m}`));
    if (!c.sources?.length) continue;
    const ignore = new Set(c.ignore || []);
    const paths = Object.keys(doc.paths || {}).map(toTemplate);
    const pathSet = new Set(paths);
    const all = [...routeLiterals(root, c.sources, c.routes)];
    const routes = all.filter((r) => !ignore.has(r));
    // a literal is covered when it is a contract path, or a prefix the code matches against one ("/api/forms/" + id)
    for (const r of routes) {
      const covered = pathSet.has(r) || pathSet.has(r.replace(/\/$/, "")) ||
        paths.some((p) => contractPathCovers(p, r)) ||
        (r.endsWith("/") && paths.some((p) => p.startsWith(r)));
      if (!covered) problems.push(P(file, `route ${r} is in the code (${c.sources.join(", ")}) but not in contract "${c.name}"`));
    }
    // a contract path is served when a literal names it (or its base before a {param}), or a prefix the code matches
    // against covers it ("/api/calendar/" + endpoint); ignored prefixes still count here
    const literal = new Set(all.map((r) => r.replace(/\/$/, "")));
    for (const p of paths) {
      const base = p.replace(/\/\{\}.*$/, "");
      const inCode = literal.has(p) || literal.has(base) || all.some((r) => contractPathCovers(p, r)) || all.some((r) => r.endsWith("/") && p.startsWith(r));
      if (!inCode) problems.push(P(file, `path ${p} is in contract "${c.name}" but no route literal in the code serves it`));
    }
  }
  // A project adopting capability contracts is configured even without an
  // explicit HTTP contract in kit.canon.json. Applicability cannot discard
  // rejected capabilities as a successful "no-http-surface" exemption.
  const adoptedCapabilities = existsSync(join(root, "contracts/capabilities.json"));
  problems.push(...capabilityContractProblems(root, kit));
  const checked = n + (adoptedCapabilities ? 1 : 0);
  return { ok: !problems.length, configured: checked > 0, checked, summary: `${checked} canonical contract${checked === 1 ? "" : "s"}`, problems };
}

/** The strings of the data a canon `schemas` rule validates, per module file: Map(file → Set of string values). Loaded exactly as the schemas check loads them. */
export async function validatedStrings(root, canon) {
  const out = new Map();
  const walkValue = (v, set, seen = new Set()) => {
    if (typeof v === "string") set.add(v);
    else if (v && typeof v === "object" && !seen.has(v)) { seen.add(v); for (const x of Array.isArray(v) ? v : Object.values(v)) walkValue(x, set, seen); }
  };
  for (const rule of canon.schemas || []) {
    if (!rule.module) continue;
    let value;
    try { value = await moduleValue(root, rule); } catch { continue; }       // the schemas check reports a module that cannot load
    const file = rule.module.replace(/^\.\//, "");
    walkValue(value, out.get(file) || out.set(file, new Set()).get(file));
  }
  return out;
}

/** hardcoding: the scan, the allow-list (validated) and its stale entries. */
export async function checkHardcoding(root, canon, kit = bundled()) {
  const cfg = canon.hardcoding;
  if (!cfg) return { ok: false, configured: false, checked: 0, summary: "NOT CONFIGURED", problems: [], findings: [], allowed: [] };
  const problems = [];
  let allow = { entries: [] };
  if (cfg.allow) {
    if (!existsSync(join(root, cfg.allow))) problems.push(P(cfg.allow, "allow-list declared but missing"));
    else {
      // validate first, then use: an allow-list off its schema is reported and the scan does not run on it
      try { allow = readJson(root, cfg.allow); } catch (e) { problems.push(P(cfg.allow, `not JSON: ${e.message}`)); return { ok: false, configured: true, checked: 0, summary: `${cfg.allow}: unreadable, nothing scanned`, problems, findings: [], allowed: [] }; }
      const invalid = formatProblems(kit.validator.validate(allow, kit.byName("canon-allow")));
      if (invalid.length) return { ok: false, configured: true, checked: 0, summary: `${cfg.allow}: invalid, nothing scanned`, problems: invalid.map((m) => P(cfg.allow, m)), findings: [], allowed: [] };
    }
  }
  const strings = await validatedStrings(root, canon);
  const r = scanHardcoding(root, cfg, { registry: kit.registry, allow, covered: (f) => strings.get(f) || null, tokenSources: canon.tokens?.sources || [] });
  for (const f of r.findings) problems.push(P(`${f.file}:${f.line}`, `${f.category}: ${f.match}`));
  for (const e of r.stale) problems.push(P(cfg.allow, `stale allow-list entry (matches nothing; remove it): ${e.file} ${e.category} "${e.match}"`));
  const counts = countBy(r.findings);
  const summary = `${r.files} file${r.files === 1 ? "" : "s"}; ${r.findings.length} finding${r.findings.length === 1 ? "" : "s"}${r.findings.length ? ` (${Object.entries(counts).map(([k, v]) => `${k} ${v}`).join(", ")})` : ""}, ${r.allowed.length} allowed`;
  return { ok: !problems.length, configured: true, checked: r.files, summary, problems, findings: r.findings, allowed: r.allowed };
}

/** freshness: each generator's check command exits 0. */
export async function checkFreshness(root, canon, spawn) {
  const problems = [];
  const n = (canon.freshness || []).length;
  if (n && !spawn) return { ok: false, configured: true, checked: 0, summary: "cannot run", problems: [P("freshness", "the generators' check commands cannot run without a spawn function (a skipped check is not a pass)")] };
  for (const f of canon.freshness || []) {
    const code = await spawn("sh", ["-c", f.command], { cwd: root });
    if (code !== 0) problems.push(P(f.outputs?.join(", ") || f.name, `stale: "${f.command}" exited ${code} (regenerate; never hand-edit generated files)`));
  }
  return { ok: !problems.length, configured: n > 0, checked: n, summary: `${n} generator${n === 1 ? "" : "s"}`, problems };
}

/** diagrams: the kit diagrams check rules, when the canon declares a diagram directory. */
export function checkDiagrams(root, canon) {
  if (!canon.diagrams) return { ok: false, configured: false, checked: 0, summary: "NOT CONFIGURED", problems: [] };
  const r = checkDiagramRepo(root, { project: canon.project });
  const problems = r.problems.map((p) => P(p.file, p.problem));
  return { ok: !problems.length, configured: true, checked: r.counts.mmd + r.counts.blocks, summary: `${r.counts.mmd} sources, ${r.counts.blocks} Markdown blocks, ${r.counts.ids} ids`, problems };
}

/**
 * digits: every number a reader sees on a Persian page is in Persian digits (docs/CONSTITUTION.md §7). Runs the
 * optional render command first (it writes rendered pages, e.g. Worker routes, into render.dir), then scans the
 * declared files and the rendered ones: HTML (when <html lang="fa…"> or a fragment), SVG, Markdown and .txt.
 */
export async function checkDigits(root, canon, spawn) {
  const cfg = canon.digits;
  if (!cfg) return { ok: false, configured: false, checked: 0, summary: "NOT CONFIGURED", problems: [] };
  const problems = [];
  if (cfg.render) {
    if (!spawn) return { ok: false, configured: true, checked: 0, summary: "cannot run", problems: [P(cfg.render.dir, "the render command cannot run without a spawn function (a skipped check is not a pass)")] };
    const code = await spawn("sh", ["-c", cfg.render.command], { cwd: root });
    if (code !== 0) problems.push(P(cfg.render.dir, `render command "${cfg.render.command}" exited ${code}`));
  }
  const exclude = (cfg.exclude || []).map((e) => e.files);
  const patterns = [...(cfg.files || []), ...(cfg.render ? [`${cfg.render.dir.replace(/\/$/, "")}/**`] : [])];
  const files = expand(root, patterns).filter((f) => typeOf(f) && !matchesAny(f, exclude));
  if (!files.length) problems.push(P((cfg.files || []).join(", "), "matches no file (declare the rendered output to scan)"));
  let scanned = 0, findings = 0;
  for (const f of files) {
    const src = readText(root, f);
    if (typeOf(f) === "html" && /<html\b/i.test(src.slice(0, 2000)) && !isPersianHtml(src)) continue;
    scanned++;
    for (const x of scanDigits(src, { file: f })) { findings++; problems.push(P(`${f}:${x.line}`, `${x.kind} ${x.where} «${x.match}» in "${x.context}"`)); }
  }
  for (const e of cfg.exclude || []) if (!expand(root, [e.files]).length) problems.push(P(e.files, "stale exclude (matches no file; remove it)"));
  return { ok: !problems.length, configured: true, checked: scanned, summary: `${scanned} Persian file${scanned === 1 ? "" : "s"} scanned; ${findings} number${findings === 1 ? "" : "s"} not in Persian digits`, problems };
}

/** vendor: the vendored kit snapshot against its manifest, when the canon declares one, and within its bound of kit main (vendor-stale). */
export async function checkVendoredKit(root, canon, kitIn, staleDeps = {}) {
  if (!canon.vendor) return { ok: false, configured: false, checked: 0, summary: "NOT CONFIGURED", problems: [] };
  const kit = kitIn || bundled();
  if (isSourceMode(canon.vendor)) {
    // the kit at t=0 (docs/FRESHNESS.md): the checkout is the kit's published head, clean, and the site holds the bootstrap, the ignore rule and no snapshot dependency
    const problems = siteProblems(root, canon.vendor);
    let record = null;
    try { record = await verifySource(root, sourceConfig(canon), { fetch: staleDeps.fetch }); } catch (e) { if (!(e instanceof SourceError)) throw e; problems.push(P(kitLocation(canon.vendor).path, e.message)); }
    if (record) for (const m of formatProblems(kit.validator.validate(record, kit.byName("kit-source")))) problems.push(P(kitLocation(canon.vendor).path, `kit.kit-source.v1: ${m}`));
    return { ok: !problems.length, configured: true, checked: 1 + (record ? 1 : 0), summary: record ? `the kit at its head ${record.sha.slice(0, 12)} (source mode, t=0, verified against ${record.published.url})` : `${kitLocation(canon.vendor).path} (source mode)`, problems };
  }
  const { manifest, problems } = checkVendor(root, canon.vendor);
  if (manifest) for (const m of formatProblems(kit.validator.validate(manifest, kit.byName("vendor-manifest")))) problems.push(P(`${canon.vendor.path}.manifest.json`, `vendor-manifest: ${m}`));
  let warnings = [];
  if (manifest?.source?.commit) {
    const s = await staleProblems(manifest, canon.vendor, staleDeps);
    for (const m of s.problems) problems.push(P(`${canon.vendor.path}.manifest.json`, m));
    warnings = s.warnings;
    for (const w of warnings) console.warn(`warning: ${w}`);
  }
  return { ok: !problems.length, configured: true, checked: manifest ? manifest.files.length : 0, summary: manifest ? `${manifest.files.length} files at ${manifest.source.commit.slice(0, 12)}` : canon.vendor.path, problems };
}

/** sdk: every OpenAPI contract has a current, untouched Forge-generated SDK and no hand-written duplicate (docs/SDK.md). */
export async function checkSdkRepo(root, canon, kit = bundled()) {
  const validate = (value, name) => formatProblems(kit.validator.validate(value, kit.byName(name)));
  return checkSdk(root, { canon, registry: kit.registry, validate });
}

/**
 * t=0: every check hands back an explicit signal, `{ configured: boolean, checked: number }`, and the kit decides from facts about the
 * repository (facts.js) whether the check applies. No string is matched and no free text waives anything:
 *
 *   configured, checked > 0                      passes (when its own problems are empty)
 *   configured, checked = 0                      FAILS: it looked at nothing
 *   not configured, no declaration               FAILS: NOT CONFIGURED
 *   notApplicable.<check>.predicate holds        passes as "not applicable": the kit proved the predicate from the files
 *   notApplicable.<check>.predicate does not     FAILS: the check applies
 *   notApplicable for a configured check         FAILS: stale
 *   claude                                       can never be declared not applicable
 */
export function applicability(name, r, canon, facts) {
  const na = canon.notApplicable?.[name];
  if (r.notApplicable === true && (name === "concepts" || name === "migrations") && !na) return r;   // proven from the files (facts.conceptSeries; no migrations/*.sql and no D1 migrations_dir), no declaration to make
  const configured = r.configured === true;
  if (ALWAYS.includes(name) && na) return { ...r, ok: false, problems: [...r.problems, P(CANON_FILE, `notApplicable.${name}: ${name} runs in every repository and cannot be declared not applicable`)] };
  if (configured && na) return { ...r, ok: false, problems: [...r.problems, P(CANON_FILE, `notApplicable.${name} is declared but ${name} is configured: remove the declaration (stale)`)] };
  if (configured) {
    if (r.checked > 0 || !r.ok) return r;
    return { ...r, ok: false, problems: [...r.problems, P(CANON_FILE, `${name} is configured but checked nothing (checked = 0): point it at the files it is meant to cover`)] };
  }
  if (na) {
    const pred = PREDICATES[na.predicate];
    if (!pred || !pred.checks.includes(name)) return { ok: false, configured: false, checked: 0, summary: "NOT CONFIGURED", problems: [P(CANON_FILE, `notApplicable.${name}: predicate "${na.predicate}" does not apply to ${name} (${Object.entries(PREDICATES).filter(([, p]) => p.checks.includes(name)).map(([id]) => id).join(", ") || "none: this check cannot be declared not applicable"})`)] };
    if (!pred.holds(facts)) return { ok: false, configured: false, checked: 0, summary: "NOT CONFIGURED", problems: [P(CANON_FILE, `notApplicable.${name}: the predicate "${na.predicate}" does not hold: ${name} applies to this repository. Configure it in ${CANON_FILE} (the predicate needs: ${pred.fact})`)] };
    return { ok: true, configured: false, checked: 0, summary: `not applicable (${na.predicate}: ${pred.fact})`, problems: [], notApplicable: true };
  }
  return { ok: false, configured: false, checked: 0, summary: "NOT CONFIGURED", problems: [...r.problems, P(CANON_FILE, `${name}: NOT CONFIGURED. Configure it in ${CANON_FILE}, or, when a fact about the repository makes it not apply, declare "notApplicable": { "${name}": { "predicate": "${Object.entries(PREDICATES).find(([, p]) => p.checks.includes(name))?.[0] || "…"}" } } (the kit proves the predicate from the files; docs/CONSTITUTION.md, t=0)`)] };
}

/**
 * concepts: the kit project registry says whether the project has a concept series; it is then checked, always (not the file's existence). A Shariah series has its signed ledger verified here, in npm test.
 */
async function checkConceptSeries(root, kit, facts, canon) {
  // The OWNER-SIGNED trust record decides whether this project has a concept series (and of which kind), never the presence of a file: deleting
  // concepts.config.json cannot switch the gate off, a record that does not verify fails (it is not "no series"), and adding a config the owner has not signed for fails.
  const ap = await kit.approvals(canon.project);
  const hasRecord = (kit.trust?.records || []).some((r) => r?.project === canon.project);
  if (!ap.known && hasRecord) return { ok: false, configured: true, checked: 1, summary: "trust record does not verify", problems: ap.problems.map((m) => P("kit trust record", m)) };
  const registered = ap.known && ap.concepts != null;
  if (!registered && !facts.conceptSeries) return { ok: true, configured: false, checked: 0, summary: `not applicable (the owner-signed trust record names no concept series for ${canon.project})`, problems: [], notApplicable: true };   // no owner-signed record names a series and no concepts.config.json exists: nothing here to approve, proven from the files
  if (!registered) return { ok: false, configured: true, checked: 1, summary: "unregistered concept series", problems: [P("concepts.config.json", `${canon.project} has a concepts.config.json but no owner-signed trust record names a concept series for it: the owner signs who may approve what (kit trust) before the series exists`)] };
  if (!facts.conceptSeries) return { ok: false, configured: true, checked: 1, summary: "concepts.config.json missing", problems: [P("concepts.config.json", `the owner-signed trust record says ${canon.project} has a ${ap.concepts} concept series but concepts.config.json is missing: the gate cannot be removed by deleting the file`)] };
  const r = await checkConceptsRepo(root, kit);
  return { ok: r.ok, configured: true, checked: r.status?.concepts ?? 1, summary: r.summary, problems: r.problems };
}

/** kit.canon.json and canon.allow.json are CODEOWNERS-covered: a waiver cannot change without the owner's review. */
export function governanceProblems(root, canon) {
  const out = [];
  for (const f of [CANON_FILE, ...(canon.hardcoding?.allow ? [canon.hardcoding.allow] : []), ...(canon.tokens?.allow ? [canon.tokens.allow] : [])].filter((x, i, a) => a.indexOf(x) === i)) {
    const c = codeownersCover(root, f);
    if (!c) out.push(P(f, `not covered by CODEOWNERS: add "/${f} @<owner>" (.github/CODEOWNERS) so a waiver, an allow-list entry or a changed canon cannot merge without the owner's review`));
    else if (c.owners.some((o) => /^@(OWNER|YOUR-HANDLE)$/.test(o))) out.push(P(c.file, `${f} is owned by the placeholder ${c.owners.join(" ")}: replace it with the owner's GitHub handle`));
  }
  return out;
}

/** Every check (or `only`) against root's kit.canon.json. */
export async function runCanon(root, { only = CHECKS, spawn, govern = only === CHECKS, kit = bundled() } = {}) {
  const { canon, problems } = loadCanon(root, kit);
  const results = { canon: { ok: !problems.length, summary: CANON_FILE, problems } };
  // validate first, then use: a kit.canon.json off its schema is reported and no check reads it
  if (!canon || problems.length) return { ok: false, results };
  if (govern) {          // the whole canon run: the waivers need the owner's review (a subset run is a focused look, not the gate)
    const gov = governanceProblems(root, canon);
    results.canon = { ok: !gov.length, summary: `${CANON_FILE}, owner-reviewed`, problems: gov };
  }
  const facts = repoFacts(root, canon);
  for (const name of only) {
    results[name] = await runOne(root, canon, kit, name, spawn, facts);
  }
  return { ok: Object.values(results).every((r) => r.ok), results };
}

async function runOne(root, canon, kit, name, spawn, facts) {
  let r;
  if (name === "schemas") r = await checkSchemas(root, canon, kit);
  else if (name === "contracts") r = checkContracts(root, canon, kit);
  else if (name === "sdk") r = await checkSdkRepo(root, canon, kit);
  else if (name === "hardcoding") r = await checkHardcoding(root, canon, kit);
  else if (name === "freshness") r = await checkFreshness(root, canon, spawn);
  else if (name === "diagrams") r = checkDiagrams(root, canon);
  else if (name === "digits") r = await checkDigits(root, canon, spawn);
  else if (name === "persian") r = await checkPersian(root, canon, kit);
  else if (name === "vendor") r = await checkVendoredKit(root, canon, kit);
  else if (name === "spelling") r = checkSpelling(root, canon, kit);
  else if (name === "tokens") r = await checkTokenLiterals(root, canon);
  else if (name === "claude") r = checkClaude(root, canon, kit);
  else if (name === "enforcement") r = checkEnforcement(root, canon, kit, CHECKS);
  else if (name === "resilience") r = await checkResilience(root, canon, kit);
  else if (name === "release") r = await checkRelease(root, canon, kit);
  else if (name === "concepts") r = await checkConceptSeries(root, kit, facts, canon);
  else if (name === "findings") r = await checkFindings(root, canon, kit);
  else if (name === "migrations") r = migrationsCheck(root, canon);
  else throw new Error(`unknown canon check "${name}" (one of ${CHECKS.join(", ")})`);
  const out = applicability(name, r, canon, facts);
  if (name === "resilience") {   // whether or not the check applies: an unreadable config candidate and a stale not-deployed entry fail
    const d = deployScan(root, canon);
    const extra = [...d.problems, ...d.stale.map((e) => ({ file: canon.hardcoding?.allow || "canon.allow.json", problem: `stale not-deployed entry (matches nothing; remove it): ${e.file} "${e.match}"` }))];
    if (extra.length) return { ...out, ok: false, problems: [...out.problems, ...extra] };
  }
  return out;
}

export { walk, scanHardcoding };
